def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = set(v for row in grid for v in row)
    colors.discard(5)  # background in the test; infer line color below

    # Find the dominant non-background line color.
    from collections import Counter
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    line = max((c for c in cnt if c != bg), key=lambda c: cnt[c])

    # Fill interiors of completely outlined rectangles.
    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    if (all(grid[r1][c] == line for c in range(c1, c2 + 1)) and
                        all(grid[r2][c] == line for c in range(c1, c2 + 1)) and
                        all(grid[r][c1] == line for r in range(r1, r2 + 1)) and
                        all(grid[r][c2] == line for r in range(r1, r2 + 1))):
                        for r in range(r1 + 1, r2):
                            for c in range(c1 + 1, c2):
                                if grid[r][c] != line:
                                    out[r][c] = 4
    return out
